INSERT INTO academy.lessons(id,module_id,revision,draft,author_id,published_revision,published_body) VALUES('academy-anatomy','module-anatomy',1,'{"id": "academy-anatomy", "courseId": "course-anatomy", "moduleId": "module-anatomy", "revision": 1, "title": {"ar": "قراءة البنية والوظيفة", "en": "Reading structure and function"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "افتح صفحة القلب في أطلس التطبيق. سجّل اسم تركيب بالعربية والإنجليزية واللاتينية، ثم افصل وصف موضعه عن وصف وظيفته. افحص مصدر الصفحة وحالة مراجعتها قبل استعمالها في تقرير. المجسم التخطيطي وسيلة تعليم، وليس تصويرًا تشخيصيًا لمريض.", "en": "Open the heart page in the app atlas. Record one structure in Arabic, English and Latin, then distinguish its location from its function. Check the page source and review status before using it in a report. A schematic model is a learning aid, not patient diagnostic imaging."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "anatomy-1", "prompt": {"ar": "هل المجسم التخطيطي فحص تشخيصي لمريض؟", "en": "Is a schematic model a patient diagnostic examination?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "anatomy-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb,'original-educational-seed',1,'{"id": "academy-anatomy", "courseId": "course-anatomy", "moduleId": "module-anatomy", "revision": 1, "title": {"ar": "قراءة البنية والوظيفة", "en": "Reading structure and function"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "افتح صفحة القلب في أطلس التطبيق. سجّل اسم تركيب بالعربية والإنجليزية واللاتينية، ثم افصل وصف موضعه عن وصف وظيفته. افحص مصدر الصفحة وحالة مراجعتها قبل استعمالها في تقرير. المجسم التخطيطي وسيلة تعليم، وليس تصويرًا تشخيصيًا لمريض.", "en": "Open the heart page in the app atlas. Record one structure in Arabic, English and Latin, then distinguish its location from its function. Check the page source and review status before using it in a report. A schematic model is a learning aid, not patient diagnostic imaging."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "anatomy-1", "prompt": {"ar": "هل المجسم التخطيطي فحص تشخيصي لمريض؟", "en": "Is a schematic model a patient diagnostic examination?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "anatomy-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb) ON CONFLICT DO NOTHING;
