INSERT INTO academy.lessons(id,module_id,revision,draft,author_id,published_revision,published_body) VALUES('academy-toxicology','module-toxicology',1,'{"id": "academy-toxicology", "courseId": "course-toxicology", "moduleId": "module-toxicology", "revision": 1, "title": {"ar": "تقييم المعلومات في محاكاة التعرض", "en": "Evaluating information in an exposure simulation"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "محاكاة تعليمية: وُجدت عبوة مجهولة في سجل تدريب. المهمة هي تحديد المعلومات الناقصة: هوية المادة، وطريق التعرض، والزمن، ووحدات الكمية ومصدرها. لا تفترض هوية المادة من لون العبوة ولا تستنتج علاجًا أو ترياقًا من هذا النشاط. دوّن عدم اليقين وأحِل القرار إلى مختص مؤهل.", "en": "Training simulation: an unidentified container appears in a practice record. Identify missing information: substance identity, exposure route, time, amount units and their source. Do not infer substance identity from container color or infer a treatment or antidote from this activity. Document uncertainty and refer decisions to a qualified specialist."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "toxicology-1", "prompt": {"ar": "هل يكفي لون العبوة لتحديد المادة؟", "en": "Is container color sufficient to identify a substance?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "toxicology-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": true}'::jsonb,'original-educational-seed',1,'{"id": "academy-toxicology", "courseId": "course-toxicology", "moduleId": "module-toxicology", "revision": 1, "title": {"ar": "تقييم المعلومات في محاكاة التعرض", "en": "Evaluating information in an exposure simulation"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "محاكاة تعليمية: وُجدت عبوة مجهولة في سجل تدريب. المهمة هي تحديد المعلومات الناقصة: هوية المادة، وطريق التعرض، والزمن، ووحدات الكمية ومصدرها. لا تفترض هوية المادة من لون العبوة ولا تستنتج علاجًا أو ترياقًا من هذا النشاط. دوّن عدم اليقين وأحِل القرار إلى مختص مؤهل.", "en": "Training simulation: an unidentified container appears in a practice record. Identify missing information: substance identity, exposure route, time, amount units and their source. Do not infer substance identity from container color or infer a treatment or antidote from this activity. Document uncertainty and refer decisions to a qualified specialist."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "toxicology-1", "prompt": {"ar": "هل يكفي لون العبوة لتحديد المادة؟", "en": "Is container color sufficient to identify a substance?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "toxicology-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": true}'::jsonb) ON CONFLICT DO NOTHING;
