INSERT INTO academy.lessons(id,module_id,revision,draft,author_id,published_revision,published_body) VALUES('academy-clinical','module-clinical',1,'{"id": "academy-clinical", "courseId": "course-clinical", "moduleId": "module-clinical", "revision": 1, "title": {"ar": "تنظيم مراجعة قائمة دوائية افتراضية", "en": "Organizing a fictional medication-list review"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "حالة محاكاة: لدى سجل تعليمي قائمتان مختلفتان للأدوية. قارن الاسم العلمي والشكل والتركيز ومصدر كل قائمة وتاريخها، واكتب مواضع الاختلاف دون تقرير إيقاف أو بدء علاج. وجود اسم في قائمة لا يثبت أن المريض يتناوله الآن. اربط كل ملاحظة بمصدرها وبيّن ما يحتاج تحققًا بشريًا.", "en": "Simulation: a training record contains two different medication lists. Compare generic name, formulation, strength, source and date; record discrepancies without deciding to start or stop treatment. A listed name does not establish current use. Link each observation to its source and mark what needs human verification."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "clinical-1", "prompt": {"ar": "هل تُحسم الخلافات بين القائمتين بالتخمين؟", "en": "Should discrepancies be resolved by guessing?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "clinical-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": true}'::jsonb,'original-educational-seed',1,'{"id": "academy-clinical", "courseId": "course-clinical", "moduleId": "module-clinical", "revision": 1, "title": {"ar": "تنظيم مراجعة قائمة دوائية افتراضية", "en": "Organizing a fictional medication-list review"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "حالة محاكاة: لدى سجل تعليمي قائمتان مختلفتان للأدوية. قارن الاسم العلمي والشكل والتركيز ومصدر كل قائمة وتاريخها، واكتب مواضع الاختلاف دون تقرير إيقاف أو بدء علاج. وجود اسم في قائمة لا يثبت أن المريض يتناوله الآن. اربط كل ملاحظة بمصدرها وبيّن ما يحتاج تحققًا بشريًا.", "en": "Simulation: a training record contains two different medication lists. Compare generic name, formulation, strength, source and date; record discrepancies without deciding to start or stop treatment. A listed name does not establish current use. Link each observation to its source and mark what needs human verification."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "clinical-1", "prompt": {"ar": "هل تُحسم الخلافات بين القائمتين بالتخمين؟", "en": "Should discrepancies be resolved by guessing?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "clinical-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": true}'::jsonb) ON CONFLICT DO NOTHING;
