INSERT INTO academy.lessons(id,module_id,revision,draft,author_id,published_revision,published_body) VALUES('academy-interactions','module-interactions',1,'{"id": "academy-interactions", "courseId": "course-interactions", "moduleId": "module-interactions", "revision": 1, "title": {"ar": "قراءة ادعاء تداخل بصورة نقدية", "en": "Critically reading an interaction claim"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "نشاط أصيل: أنشئ بطاقة تقييم لادعاء تداخل، تتضمن المادة الفعالة الأخرى، ونوع الدليل، وتاريخه وسياقه وحدود انطباقه. نتيجة بحث آلية واحدة ليست قرارًا فرديًا. في هذا التطبيق تُعرض الحقائق السريرية المنشورة فقط بعد اجتياز بوابة المراجعة؛ عدم وجود سجل منشور لا يثبت عدم وجود تداخل.", "en": "Original activity: build an evaluation card for an interaction claim, recording the other ingredient, evidence type, date, context and applicability limits. One automated search result is not an individual decision. This app exposes published clinical facts only after the review gate; absence of a published record does not establish absence of an interaction."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "interactions-1", "prompt": {"ar": "هل غياب سجل في التطبيق ينفي وجود تداخل؟", "en": "Does absence of an app record rule out an interaction?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "interactions-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb,'original-educational-seed',1,'{"id": "academy-interactions", "courseId": "course-interactions", "moduleId": "module-interactions", "revision": 1, "title": {"ar": "قراءة ادعاء تداخل بصورة نقدية", "en": "Critically reading an interaction claim"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "نشاط أصيل: أنشئ بطاقة تقييم لادعاء تداخل، تتضمن المادة الفعالة الأخرى، ونوع الدليل، وتاريخه وسياقه وحدود انطباقه. نتيجة بحث آلية واحدة ليست قرارًا فرديًا. في هذا التطبيق تُعرض الحقائق السريرية المنشورة فقط بعد اجتياز بوابة المراجعة؛ عدم وجود سجل منشور لا يثبت عدم وجود تداخل.", "en": "Original activity: build an evaluation card for an interaction claim, recording the other ingredient, evidence type, date, context and applicability limits. One automated search result is not an individual decision. This app exposes published clinical facts only after the review gate; absence of a published record does not establish absence of an interaction."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "interactions-1", "prompt": {"ar": "هل غياب سجل في التطبيق ينفي وجود تداخل؟", "en": "Does absence of an app record rule out an interaction?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "interactions-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb) ON CONFLICT DO NOTHING;
