INSERT INTO academy.lessons(id,module_id,revision,draft,author_id,published_revision,published_body) VALUES('academy-professional','module-professional',1,'{"id": "academy-professional", "courseId": "course-professional", "moduleId": "module-professional", "revision": 1, "title": {"ar": "التوثيق والخصوصية وحدود الدليل", "en": "Documentation, privacy and evidence limits"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "اكتب ملاحظة تدريبية دون أسماء مرضى أو معرفات شخصية. افصل ما شوهد عما استُنتج وما بقي مجهولًا. سجّل المصدر وتاريخ الاطلاع وحالة المراجعة. لا تُعدّل ملاحظة منشورة بصمت: احتفظ بنسختها ثم أنشئ مسودة جديدة، واطلب مراجعة مستقلة قبل نشرها.", "en": "Write a training note without patient names or personal identifiers. Separate observations, inferences and unknowns. Record the source, access date and review status. Do not silently overwrite a published note: retain its version, create a new draft and seek independent review before publication."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "professional-1", "prompt": {"ar": "هل ينبغي إدخال هوية مريض حقيقي في هذا النشاط؟", "en": "Should a real patient identity be entered in this activity?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "professional-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb,'original-educational-seed',1,'{"id": "academy-professional", "courseId": "course-professional", "moduleId": "module-professional", "revision": 1, "title": {"ar": "التوثيق والخصوصية وحدود الدليل", "en": "Documentation, privacy and evidence limits"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "اكتب ملاحظة تدريبية دون أسماء مرضى أو معرفات شخصية. افصل ما شوهد عما استُنتج وما بقي مجهولًا. سجّل المصدر وتاريخ الاطلاع وحالة المراجعة. لا تُعدّل ملاحظة منشورة بصمت: احتفظ بنسختها ثم أنشئ مسودة جديدة، واطلب مراجعة مستقلة قبل نشرها.", "en": "Write a training note without patient names or personal identifiers. Separate observations, inferences and unknowns. Record the source, access date and review status. Do not silently overwrite a published note: retain its version, create a new draft and seek independent review before publication."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "professional-1", "prompt": {"ar": "هل ينبغي إدخال هوية مريض حقيقي في هذا النشاط؟", "en": "Should a real patient identity be entered in this activity?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "professional-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb) ON CONFLICT DO NOTHING;
