INSERT INTO academy.lessons(id,module_id,revision,draft,author_id,published_revision,published_body) VALUES('academy-regional','module-regional',1,'{"id": "academy-regional", "courseId": "course-regional", "moduleId": "module-regional", "revision": 1, "title": {"ar": "التمييز بين التسجيل والتوفر", "en": "Distinguishing registration from availability"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "صمّم نموذج تحقق لمنتج يتضمن الدولة والجهة الرقابية ورقم التسجيل والشركة والشكل والتركيز ورابط الدليل وتاريخه. لا تنشئ اسمًا تجاريًا بالتخمين. التسجيل معلومة منفصلة عن التوفر في صيدلية بعينها؛ دوّن مصدرًا منفصلًا وتاريخًا لأي ادعاء توفر. لا تعرض سعرًا بلا دليل مؤرخ.", "en": "Design a product-verification record with country, regulator, registration number, manufacturer, formulation, strength, evidence URL and date. Do not invent a brand name. Registration is separate from availability at a particular pharmacy; record a separate dated source for any availability claim. Do not display a price without dated evidence."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "regional-1", "prompt": {"ar": "هل يكفي التسجيل لإثبات توفر المنتج في كل صيدلية؟", "en": "Does registration prove availability at every pharmacy?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "regional-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb,'original-educational-seed',1,'{"id": "academy-regional", "courseId": "course-regional", "moduleId": "module-regional", "revision": 1, "title": {"ar": "التمييز بين التسجيل والتوفر", "en": "Distinguishing registration from availability"}, "outcomes": [{"ar": "تمييز المعلومة الموثقة من الافتراض.", "en": "Distinguish sourced information from assumptions."}, {"ar": "كتابة ملاحظة تعليمية قابلة للمراجعة.", "en": "Write a reviewable educational note."}], "body": {"ar": "صمّم نموذج تحقق لمنتج يتضمن الدولة والجهة الرقابية ورقم التسجيل والشركة والشكل والتركيز ورابط الدليل وتاريخه. لا تنشئ اسمًا تجاريًا بالتخمين. التسجيل معلومة منفصلة عن التوفر في صيدلية بعينها؛ دوّن مصدرًا منفصلًا وتاريخًا لأي ادعاء توفر. لا تعرض سعرًا بلا دليل مؤرخ.", "en": "Design a product-verification record with country, regulator, registration number, manufacturer, formulation, strength, evidence URL and date. Do not invent a brand name. Registration is separate from availability at a particular pharmacy; record a separate dated source for any availability claim. Do not display a price without dated evidence."}, "example": {"ar": "تطبيق: اكتب جدولًا صغيرًا للمعلومة ومصدرها وحالة التحقق، ثم أجب عن السؤالين.", "en": "Exercise: make a short table of information, source and verification state, then answer both questions."}, "questions": [{"id": "regional-1", "prompt": {"ar": "هل يكفي التسجيل لإثبات توفر المنتج في كل صيدلية؟", "en": "Does registration prove availability at every pharmacy?"}, "options": [{"ar": "نعم", "en": "Yes"}, {"ar": "لا", "en": "No"}], "correctIndex": 1, "explanation": {"ar": "لا؛ يجب التحقق من الدليل والسياق بدل الافتراض.", "en": "No; verify evidence and context instead of assuming."}}, {"id": "regional-2", "prompt": {"ar": "ما الخطوة الأنسب عند نقص الدليل؟", "en": "What is appropriate when evidence is missing?"}, "options": [{"ar": "اختلاق المعلومة", "en": "Invent the information"}, {"ar": "توثيق النقص وطلب تحقق مؤهل", "en": "Document the gap and seek qualified verification"}], "correctIndex": 1, "explanation": {"ar": "تُسجَّل حدود المعرفة بدل تقديم يقين غير موثق.", "en": "Record knowledge limits rather than unsupported certainty."}}], "sourceIds": ["src-academy-original"], "reviewStatus": "EDUCATIONAL_UNREVIEWED", "license": "CC BY 4.0", "attribution": "Original Dawa & Hayah learning activity, 2026; scientific review pending.", "isSimulation": false}'::jsonb) ON CONFLICT DO NOTHING;
